const db = window.supabase.createClient(
  "https://ogpmyfkbqrvfeoodhqva.supabase.co",
  "sb_publishable_xAcsee1CId20r8yweYxdIg_2KcxDwr_"
);

const form = document.getElementById("bookingForm");
const message = document.getElementById("message");
const list = document.getElementById("bookingList");
const count = document.getElementById("count");

const bookingCardBackground = "data:image/jpeg;base64,";

// Add the site designer credit directly beneath the main page heading.
const pageHeading = Array.from(document.querySelectorAll("h1")).find(el =>
  el.textContent.includes("حجز قاعة دار مريم")
) || document.querySelector("h1");
if (pageHeading && !document.getElementById("siteDesignerCredit")) {
  const credit = document.createElement("p");
  credit.id = "siteDesignerCredit";
  credit.textContent = "تصميم الموقع: أ/دانه ساكت المحيني";
  credit.style.cssText = "margin:6px 0 18px;text-align:center;font-size:14px;color:#c5a45b;font-weight:600;";
  pageHeading.insertAdjacentElement("afterend", credit);
}

// Public page reads only the fields needed to show the schedule.
const readBookings = async () => {
  const { data, error } = await db
    .from("hall_booking")
    .select("id,teacher_name,purpose,booking_date,start_time,end_time")
    .order("booking_date", { ascending: true });

  if (error) {
    console.error(error);
    message.className = "error";
    message.textContent = "تعذر تحميل الحجوزات. تحققي من إعدادات قاعدة البيانات.";
    return [];
  }

  return data.map(b => ({
    id: b.id,
    teacher_name: b.teacher_name,
    purpose: b.purpose,
    date: b.booking_date,
    start: b.start_time,
    end: b.end_time
  }));
};

const fmtDate = date => new Date(date + "T12:00:00").toLocaleDateString("ar-KW", {
  year: "numeric",
  month: "long",
  day: "numeric"
});

function escapeHtml(s) {
  return String(s ?? "").replace(/[&<>"']/g, c => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  }[c]));
}

async function render() {
  const bookings = await readBookings();
  bookings.sort((a, b) => (a.date + a.start).localeCompare(b.date + b.start));
  count.textContent = `${bookings.length} حجز`;

  if (!bookings.length) {
    list.innerHTML = '<div class="empty">لا توجد حجوزات مسجلة للحين</div>';
    return;
  }

  list.innerHTML = bookings.map(b => `
    <article class="booking">
      <div>
        <strong>${escapeHtml(b.purpose)}</strong>
<small>${escapeHtml(b.teacher_name)}</small>
        <small>${fmtDate(b.date)} · ${escapeHtml(b.start)} - ${escapeHtml(b.end)}</small>
      </div>
    </article>
  `).join("");
}

form.addEventListener("submit", async e => {
  e.preventDefault();

  const booking = {
    teacher_name: document.getElementById("teacher").value.trim(),
    purpose: document.getElementById("purpose").value.trim(),
    booking_date: document.getElementById("date").value,
    start_time: document.getElementById("start").value,
    end_time: document.getElementById("end").value
  };

  if (
    !booking.teacher_name ||
    !booking.purpose ||
    !booking.booking_date ||
    !booking.start_time ||
    !booking.end_time ||
    booking.start_time >= booking.end_time
  ) {
    message.className = "error";
    message.textContent = "تأكدي من البيانات ووقت البداية والنهاية.";
    return;
  }

  const { data: existingBookings, error: readError } = await db
    .from("hall_booking")
    .select("booking_date,start_time,end_time")
    .eq("booking_date", booking.booking_date);

  if (readError) {
    console.error(readError);
    message.className = "error";
    message.textContent = "تعذر التحقق من الحجوزات. حاولي مرة ثانية.";
    return;
  }

  const conflict = (existingBookings || []).some(b =>
    b.start_time < booking.end_time && booking.start_time < b.end_time
  );

  if (conflict) {
    message.className = "error";
    message.textContent = "هذا الوقت محجوز، اختاري وقتًا آخر.";
    return;
  }

  const { error } = await db.from("hall_booking").insert([booking]);

  if (error) {
    console.error(error);
    message.className = "error";
    message.textContent = "تعذر حفظ الحجز. تحققي من إعدادات قاعدة البيانات.";
    return;
  }

  message.className = "success";
  message.textContent = "تم تسجيل الحجز بنجاح.";
  form.reset();
  await render();
document.getElementById("downloadCard").hidden = false;
  const card = document.getElementById("bookingCard");
  if (card) {
    card.hidden = false;
    card.innerHTML = `
      <div style="text-align:center;color:#f7ead3;background:#5b4937;border-radius:8px;padding:18px 12px;">
        <h2 style="margin:0 0 8px;font-size:30px;">دار مريم</h2>
        <h3 style="margin:0 0 22px;font-size:21px;font-weight:600;">بطاقة حجز القاعة</h3>
        <div style="display:grid;grid-template-columns:1fr 1.25fr;gap:14px 8px;text-align:right;max-width:440px;margin:0 auto;font-size:16px;">
          <strong>اسم المعلمة:</strong><span style="text-align:center;">${escapeHtml(booking.teacher_name)}</span>
          <strong>الغرض:</strong><span style="text-align:center;">${escapeHtml(booking.purpose)}</span>
          <strong>التاريخ:</strong><span style="text-align:center;">${fmtDate(booking.booking_date)}</span>
          <strong>الوقت:</strong><span style="text-align:center;direction:ltr;">${escapeHtml(booking.start_time)} - ${escapeHtml(booking.end_time)}</span>
        </div>
        <p style="margin:24px 0 10px;font-weight:700;">تم تسجيل الحجز بنجاح</p>
        <p style="margin:0;font-size:13px;">تصميم الموقع: أ/ دانة ساكت المحيني</p>
      </div>`;
    card.dataset.teacher = booking.teacher_name;
    card.dataset.purpose = booking.purpose;
    card.dataset.date = booking.booking_date;
    card.dataset.start = booking.start_time;
    card.dataset.end = booking.end_time;
  }
});

const downloadButton = document.getElementById("downloadCard");
if (downloadButton) {
  downloadButton.addEventListener("click", () => {
    const card = document.getElementById("bookingCard");
    if (!card || card.hidden || !card.dataset.teacher) {
      message.className = "error";
      message.textContent = "سجلي الحجز أولًا حتى تتمكني من تنزيل البطاقة.";
      return;
    }

    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = img.naturalWidth || 1080;
      canvas.height = img.naturalHeight || 1350;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

      const scale = canvas.width / 1080;
      ctx.textAlign = "center";
      ctx.direction = "rtl";
      ctx.fillStyle = "#f8ead1";
      ctx.shadowColor = "rgba(35, 20, 8, 0.35)";
      ctx.shadowBlur = 2;

      ctx.font = `bold ${Math.round(46 * scale)}px Arial`;
      ctx.fillText("دار مريم", canvas.width / 2, 285 * scale);
      ctx.font = `bold ${Math.round(30 * scale)}px Arial`;
      ctx.fillText("بطاقة حجز القاعة", canvas.width / 2, 345 * scale);

      const rows = [
        ["اسم المعلمة:", card.dataset.teacher],
        ["الغرض:", card.dataset.purpose],
        ["التاريخ:", new Date(card.dataset.date + "T12:00:00").toLocaleDateString("ar-KW", {year:"numeric",month:"long",day:"numeric"})],
        ["الوقت:", `${card.dataset.start} - ${card.dataset.end}`]
      ];
      const labelX = 830 * scale;
      const valueX = 465 * scale;
      let y = 465 * scale;
      ctx.font = `bold ${Math.round(27 * scale)}px Arial`;
      rows.forEach(([label, value]) => {
        ctx.textAlign = "right";
        ctx.direction = "rtl";
        ctx.fillText(label, labelX, y);
        ctx.textAlign = "center";
        ctx.fillText(value, valueX, y);
        y += 82 * scale;
      });

      ctx.textAlign = "center";
      ctx.font = `bold ${Math.round(28 * scale)}px Arial`;
      ctx.fillText("تم تسجيل الحجز بنجاح", canvas.width / 2, 930 * scale);
      ctx.font = `${Math.round(20 * scale)}px Arial`;
      ctx.fillText("تصميم الموقع: أ/ دانة ساكت المحيني", canvas.width / 2, 1005 * scale);

      canvas.toBlob(blob => {
        if (!blob) {
          message.className = "error";
          message.textContent = "تعذر تجهيز صورة البطاقة. حاولي مرة أخرى.";
          return;
        }
        const url = URL.createObjectURL(blob);
        const win = window.open("", "_blank");
        if (!win) {
          const a = document.createElement("a");
          a.href = url;
          a.download = "بطاقة-حجز-دار-مريم.png";
          a.click();
          setTimeout(() => URL.revokeObjectURL(url), 30000);
          return;
        }
        win.document.write(`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>بطاقة حجز دار مريم</title><body style="margin:0;padding:12px;text-align:center;background:#f5f0e7;font-family:Arial"><p>لحفظ البطاقة، اضغطي مطولًا على الصورة واختاري حفظ الصورة.</p><img src="${url}" alt="بطاقة حجز دار مريم" style="width:100%;max-width:700px;height:auto"></body></html>`);
        win.document.close();
        message.className = "success";
        message.textContent = "تم تجهيز البطاقة بالخلفية الأصلية. احفظي الصورة من التبويب الجديد.";
      }, "image/png");
    };
    img.onerror = () => {
      message.className = "error";
      message.textContent = "تعذر تحميل خلفية البطاقة. أعيدي تحميل الصفحة وجربي مرة أخرى.";
    };
    img.src = bookingCardBackground;
  });
}

const exportButton = document.getElementById("exportBtn");
if (exportButton) {
  exportButton.addEventListener("click", async () => {
    const bookings = await readBookings();
    const rows = [
      ["الغرض", "التاريخ", "البداية", "النهاية"],
      ...bookings.map(b => [b.purpose, b.date, b.start, b.end])
    ];
    const csv = "\uFEFF" + rows.map(row =>
      row.map(v => String(v ?? "")).join(",")
    ).join("\r\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8;" }));
    const a = document.createElement("a");
    a.href = url;
    a.download = "school-hall-bookings.csv";
    a.click();
    URL.revokeObjectURL(url);
  });
}

const clearButton = document.getElementById("clearBtn");
if (clearButton) {
  clearButton.addEventListener("click", () => {
    if (!confirm("متأكدة تبين مسح جميع الحجوزات المحفوظة؟")) return;
    message.className = "";
    message.textContent = "هذا الزر غير مفعّل حاليًا لحماية الحجوزات.";
  });
}

render();
